/* @lc app=leetcode id=3311 lang=kotlin */ class Solution { fun bfs(g: Map<Int, List<Int>>, n: Int, s: Int): IntArray = IntArray(n) { -1 }.also { it[s] = 0 }.also { d -> generateSequence(listOf(s)) { f -> f.flatMap { u -> g[u].orEmpty().filter { d[it] == -1 }.distinct().onEach { v -> d[v] = d[u] + 1 } }.takeIf { it.isNotEmpty() } }.count() } fun constructGridLayout(n: Int, edges: Array<IntArray>): Array<IntArray> = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> (0 until n).firstOrNull { g[it]!!.size == 1 }?.let { s -> arrayOf(generateSequence(s to -1) { (u, p) -> g[u]!!.firstOrNull { it != p }?.let { it to u } }.map { it.first }.toList().toIntArray()) } ?: (0 until n).first { g[it]!!.size == 2 }.let { c -> bfs(g, n, c).let { dc -> (0 until n).filter { it != c && g[it]!!.size == 2 }.minBy { dc[it] }.let { e -> bfs(g, n, e).let { de -> (0..dc[e]).map { k -> (0 until n).first { dc[it] == k && de[it] == dc[e] - k } }.let { row0 -> HashSet(row0).let { seen -> generateSequence(row0) { prev -> prev.also { seen.addAll(it) }.mapNotNull { u -> g[u]!!.firstOrNull { v -> v !in seen } }.takeIf { it.size == row0.size } }.map { it.toIntArray() }.toList().toTypedArray() } } } } } } } }